{
["Type"] = "Button",
["label"] = "Create Macros",
["tooltip"] = {
["title"] = "Create Macros",
["desc"] = "Creates macros that post numbers 1 through 8 with the matching raid-marker icons and will trigger the display mid-fight. All you have to do is press the macro's in the order you want the Knocks to be triggered during the Dmg-Amp. If new messages come in after 3 have already filled it will simply start from the beginning, that way you can fix mistakes.",
},
["func"] = "return function()\n                    local iconIDs = {\"137001\", \"137002\", \"137003\", \"137004\", \"137005\", \"137006\", \"137007\", \"137008\"}\n                    for i=1, 8 do\n                        local macroName = \"NSRT_SSZORAK_\" .. i\n                        if not GetMacroInfo(macroName) then\n                            CreateMacro(macroName, iconIDs[i], \"/raid \" .. i)\n                        else\n                            EditMacro(macroName, macroName, iconIDs[i], \"/raid \" .. i)\n                        end\n                    end\n                end",
["width"] = 150,
},
},
